<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">new_image.paste(dataset[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;image&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].resize((width, height)), (width, height))</span></span>
